{
  "schema": {
    "structure": "doc",
    "children": [
      {
        "structure": "Title",
        "description": "文档主标题，概括全文核心内容的短语或短句，通常5-20字，不含完整句子结构。",
        "required": false,
        "multiple": false
      },
      {
        "structure": "Subtitle",
        "description": "副标题，补充说明主标题的短语或短句，通常5-20字，不含完整句子结构。",
        "required": false,
        "multiple": false
      },
      {
        "structure": "Heading1",
        "description": "一级标题，概括章节主题的短语，通常3-15字，不含完整句子结构。",
        "required": false,
        "multiple": true
      },
      {
        "structure": "Heading2",
        "description": "二级标题，概括小节主题的短语，通常3-15字，不含完整句子结构。",
        "required": false,
        "multiple": true
      },
      {
        "structure": "Heading3",
