        "required": false,
        "multiple": true
      },
      {
        "structure": "Heading6",
        "description": "六级标题，概括细分内容的短语，通常3-15字，不含完整句子结构。",
        "required": false,
        "multiple": true
      },
      {
        "structure": "Heading7",
        "description": "七级标题，概括细分内容的短语，通常3-15字，不含完整句子结构。",
        "required": false,
        "multiple": true
      },
      {
        "structure": "Heading8",
        "description": "八级标题，概括细分内容的短语，通常3-15字，不含完整句子结构。",
        "required": false,
        "multiple": true
      },
      {
        "structure": "Heading9",
        "description": "九级标题，概括细分内容的短语，通常3-15字，不含完整句子结构。",
        "required": false,
        "multiple": true
      },
      {
        "structure": "Text",
        "description": "正文内容，包含完整句子的叙述性段落，通常超过15字，由一个或多个完整句子组成。",
        "required": false,
        "multiple": true
      }
    ]
  }
}

